def deleteMid(head):
	if head.next == None or head == None:
		return None
	elif head.next.next == None:
		head.next = None
	else:
		p = head
		n = 1
		while p.next != None:
			n += 1
			p = p.next
		m = n // 2
		n = 1
		p = head
		while n != m:
			n += 1
			p = p.next
		p.next = p.next.next
	return head

