class Solution:

	def max_of_subarrays(self, arr, N, K):
		result = []
		dq = deque()
		for i in range(N):
			while dq and arr[dq[-1]] < arr[i]:
				dq.pop()
			dq.append(i)
			if dq[0] <= i - K:
				dq.popleft()
			if i >= K - 1:
				result.append(arr[dq[0]])
		return result

class Fenwick:

	def __init__(self, size):
		self.size = size
		self.tree = [0] * (size + 1)

	def add(self, idx, val):
		idx = int(idx)
		while idx <= self.size:
			self.tree[idx] += val
			idx += idx & -idx

	def sum(self, idx):
		ret = 0
		idx = int(idx)
		while idx > 0:
			ret += self.tree[idx]
			idx -= idx & -idx
		return ret
