from typing import Optional
from typing import List

class Solution:

	def findPairsWithGivenSum(self, target: int, head: Optional['Node']) -> List[List[int]]:
		ans = []
		slow = head
		fast = head
		while fast.next is not None:
			fast = fast.next
		while slow.data < fast.data:
			if slow.data + fast.data == target:
				ans.append((slow.data, fast.data))
				slow = slow.next
				fast = fast.prev
			elif slow.data + fast.data < target:
				slow = slow.next
			else:
				fast = fast.prev
		return ans

from typing import Optional
from typing import List

class Solution:

	def findPairsWithGivenSum(self, target: int, head: Optional['Node']) -> List[List[int]]:
		res = []
		start = head
		end = head
		while end.next:
			end = end.next
		while start.data < end.data:
			s = start.data + end.data
			if s == target:
				res.append([start.data, end.data])
				start = start.next
				end = end.prev
			elif s < target:
				start = start.next
			else:
				end = end.prev
		return res

from typing import Optional
from typing import List

class Solution:

	def findPairsWithGivenSum(self, target: int, head: Optional['Node']) -> List[List[int]]:
		high = head
		low = head
		temp = []
		while high.next != None:
			high = high.next
		while low.data < high.data:
			sum = low.data + high.data
			if sum > target:
				high = high.prev
			elif sum < target:
				low = low.next
			else:
				temp.append([low.data, high.data])
				low = low.next
				high = high.prev
		return temp

from typing import Optional
from typing import List

class Solution(object):

	def findPairsWithGivenSum(self, target: int, head: Optional['Node']) -> List[List[int]]:
		result = []
		if not head:
			return result
		tail = head
		while tail.next:
			tail = tail.next
		while head and tail and (head.data < tail.data):
			(headVal, tailVal) = (head.data, tail.data)
			currVal = headVal + tailVal
			if currVal == target:
				result.append((headVal, tailVal))
				head = head.next
				tail = tail.prev
			elif currVal > target:
				tail = tail.prev
			else:
				head = head.next
		return result

