def comp(a, b):
	return val(a) & val(b)

def bitsub(a, b):
	c = val(a) - val(b)
	s = ''
	while c >= 1:
		s = s + str(c % 2)
		c = int(c / 2)
	s = '0' * (3 - len(s)) + s[::-1]
	return s

def val(a):
	return (ord(a[0]) - ord('0')) * 4 + (ord(a[1]) - ord('0')) * 2 + (ord(a[2]) - ord('0'))
