class Solution:

	def makesquare(self, nums):
		if len(nums) < 4:
			return False
		length = sum(nums)
		if length % 4:
			return False
		length = int(length / 4)
		nums.sort(reverse=True)
		if length < nums[0]:
			return False
		elif length == nums[0]:
			stack = list([(set([0]), 1, length, 1)])
		else:
			stack = list([(set([0]), 1, length - nums[0], 2)])
		while stack:
			(usedSet, startIndex, target, remainRounds) = stack.pop()
			for i in range(len(nums) - 1, startIndex - 1, -1):
				if i in usedSet:
					continue
				num = nums[i]
				if num < target and i + 1 < len(nums):
					stack.append((usedSet | {i}, i + 1, target - num, remainRounds))
				elif num == target:
					if remainRounds == 0:
						return True
					else:
						stack.append((usedSet | {i}, 1, length, remainRounds - 1))
		return False

class Solution:

	def makesquare(self, nums):
		total = sum(nums)
		if total % 4 != 0 or len(nums) < 4:
			return False
		size = total / 4
		nums.sort(reverse=True)
		used = [False] * len(nums)

		def dfs(i, expect):
			if i >= len(nums):
				return expect % size == 0
			if used[i]:
				return dfs(i + 1, expect)
			used[i] = True
			if nums[i] == expect:
				return True
			if nums[i] < expect:
				expect -= nums[i]
				available = [j for j in range(i + 1, len(nums)) if not used[j]]
				for x in available:
					if dfs(x, expect):
						return True
			used[i] = False
			return False
		for i in range(len(nums)):
			if not dfs(i, size):
				return False
		return True

