				load = board
		return painter <= k

	def recursion(self, arr, n, k, start, end, ans):
		if start > end:
			return ans
		mid = (start + end) // 2
		output = self.ifpossible(arr, n, k, mid)
		if output:
			ans = mid
			end = mid - 1
			return self.recursion(arr, n, k, start, end, ans)
		else:
			start = mid + 1
			return self.recursion(arr, n, k, start, end, ans)

