class Solution:

	def numTilePossibilities(self, tiles: str) -> int:

		def freq(tiles):
			d = {}
			for c in tiles:
				if c in d:
					d[c] += 1
				else:
					d[c] = 1
			return d

		def build(d, s):
			new_d = {}
			for (key, value) in d.items():
				if key == s:
					new_d[key] = value - 1
				else:
					new_d[key] = value
			return new_d

		def generate(options):
			sol = []
			for (key, value) in options.items():
				if value > 0:
					sol.append(key)
					fringe = generate(build(options, key))
					sol += fringe
					sol += [key + f for f in fringe]
			return sol
		return len(set(generate(freq(tiles))))

class Solution:

	def numTilePossibilities(self, tiles: str) -> int:

		@lru_cache(None)
		def find(s):
			if len(s) <= 1:
				return set([s])
			ret = set()
			for i in range(len(s)):
				head = s[i]
				tails = find(s[:i] + s[i + 1:])
				ret = ret.union(tails)
				for tail in tails:
					for j in range(len(tail) + 1):
						temp = tail[:j] + head + tail[j:]
						ret.add(temp)
			return ret
		res = find(tiles)
		return len(set(res))

from collections import Counter

class Solution:

	def numTilePossibilities(self, tiles: str) -> int:
		(c_all, visited) = (Counter(tiles), set())
		stack = [(x, Counter([x])) for x in c_all]
		while stack:
			(element, c) = stack.pop()
			if element not in visited:
				stack.extend([(element + x, c + Counter([x])) for x in c_all - c])
				visited.add(element)
		return len(visited)

