class Solution:

	def findPoisonedDuration(self, timeSeries, duration):
		if not timeSeries:
			return 0
		prev = timeSeries[0]
		ret = 0
		count = 0
		for t in timeSeries[1:]:
			diff = t - prev
			if diff > duration:
				count += 1
			else:
				ret += diff
			prev = t
		ret += (count + 1) * duration
		return ret

class Solution:

	def findPoisonedDuration(self, timeSeries, duration):
		if not timeSeries:
			return 0
		previous_time = timeSeries[0]
		total_time = duration
		for time in timeSeries[1:]:
			if time - previous_time < duration:
				total_time += time - previous_time
				previous_time = time
			else:
				total_time += duration
				previous_time = time
		return total_time

