def LongestPalindromeSubString(text):
	if text == text[::-1]:
		return text
	elif len(text) == 1:
		return text
	original = text[:]
	text = '@#' + '#'.join(text) + '#$'
	n = len(text)
	C = 0
	R = 0
	max = 0
	maxInd = 0
	pal = [0] * n
	for i in range(1, n - 1):
		mirr = 2 * C - i
		if i < R:
			pal[i] = min(pal[mirr], R - i)
		while text[i + (1 + pal[i])] == text[i - (1 + pal[i])]:
			pal[i] += 1
		if pal[i] > max:
			max = pal[i]
			maxInd = i
		if i + pal[i] > R:
			C = i
			R = i + pal[i]
		if i + pal[i] == n - 2:
			break
	if maxInd % 2 == 0:
		halfLen = (pal[maxInd] - 1) // 2
		maxInd = maxInd // 2 - 1
		return original[maxInd - halfLen:maxInd + halfLen + 1]
	else:
		halfLen = pal[maxInd] // 2
		maxInd = (maxInd - 1) // 2
		return original[maxInd - halfLen:maxInd + halfLen]

