class Solution:

	def recur(self, i, sm, nums):
		if (i, sm) in self.memo:
			return
		self.result[sm] = 1
		if i >= len(nums):
			return
		self.recur(i + 1, sm, nums)
		self.recur(i + 1, sm + nums[i], nums)
		self.memo[i, sm] = 1

	def DistinctSum(self, nums):
		nums.sort()
		self.result = {}
		self.memo = {}
		self.recur(0, 0, nums)
		return sorted(list(self.result))

