class Solution:

	def build_bridges(self, str1, str2):
		return self.helper(str1, str2, {})

	def helper(self, s1, s2, store):
		if not s1 or not s2:
			return 0
		if (s1, s2) in store:
			return store[s1, s2]
		if s1[0] == s2[0]:
			store[s1, s2] = self.helper(s1[1:], s2[1:], store) + 1
			return store[s1, s2]
		first = self.helper(s1[1:], s2, store)
		second = self.helper(s1, s2[1:], store)
		store[s1, s2] = max(first, second)
		return store[s1, s2]

