class Solution:

	def getXor(self, nums, a, b):
		n = len(nums)
		tree = [0] * (n + 1)

		def update_fenwick(i, val):
			while i <= n:
				tree[i] ^= val
				i += i & -i

		def get_fenwick(i):
			ans = 0
			while i:
				ans ^= tree[i]
				i -= i & -i
			return ans
		for i in range(1, len(nums) + 1):
			update_fenwick(i, nums[i - 1])
		return get_fenwick(b + 1) ^ get_fenwick(a)

def build(si, ss, se, arr, st):
	if ss > se:
		return
	elif ss == se:
		st[si] = arr[ss]
	else:
		mid = (ss + se) // 2
		build(2 * si + 1, ss, mid, arr, st)
		build(2 * si + 2, mid + 1, se, arr, st)
		st[si] = st[2 * si + 1] ^ st[2 * si + 2]

def query(si, ss, se, qs, qe, st):
	if ss > qe or se < qs:
		return 0
	elif qs <= ss and se <= qe:
		return st[si]
	else:
		mid = (ss + se) // 2
		return query(2 * si + 1, ss, mid, qs, qe, st) ^ query(2 * si + 2, mid + 1, se, qs, qe, st)

