class Solution:

	def largestSumOfAverages(self, A: List[int], K: int) -> float:
		N = len(A)
		P = [0] * (N + 1)
		for i in range(1, N + 1):
			P[i] = P[i - 1] + A[i - 1]
		Table = [(P[N] - P[i]) / (N - i) for i in range(N)]
		for k in range(2, K + 1):
			for i in range(K - k, N - k + 1):
				Table[i] = max(((P[j] - P[i]) / (j - i) + Table[j] for j in range(i + 1, N - k + 2)))
		return Table[0]

from functools import lru_cache
from itertools import accumulate

class Solution:

	def largestSumOfAverages(self, A: List[int], K: int) -> float:
		n = len(A)
		p = [0] + list(accumulate(A))

		@lru_cache(None)
		def dp(l, k):
			if k > l:
				return 0
			if k == 1:
				return p[l] / l
			return max((dp(i, k - 1) + (p[l] - p[i]) / (l - i) for i in range(k - 1, l)))
		return dp(n, K)

class Solution:

	def largestSumOfAverages(self, A: List[int], K: int) -> float:
		n = len(A)
		memo = [[0 for k in range(K)] for i in range(n)]

		def aux(A, cur, k, memo):
			if cur == len(A):
				return 0
			if memo[cur][k]:
				return memo[cur][k]
			tmp = sum(A[cur:]) / (len(A) - cur)
			if k == 0:
				memo[cur][k] = tmp
				return tmp
			for i in range(cur + 1, len(A) + 1):
				tmp = max(tmp, sum(A[cur:i]) / (i - cur) + aux(A, i, k - 1, memo))
			memo[cur][k] = tmp
			return tmp
		return aux(A, 0, K - 1, memo)

class Solution:

	def largestSumOfAverages(self, A, K: int) -> float:
		A = [0] + A
		len_a = len(A)
		dp = [[0] * (K + 1) for _ in range(len_a)]
		for i in range(1, len_a):
			dp[i][0] = -float('inf')
		for i in range(1, len_a):
			for k in range(1, min(K + 1, i + 1)):
				for j in range(k, i + 1):
					dp[i][k] = max(dp[i][k], dp[j - 1][k - 1] + self.helper(A[j:i + 1]))
		return dp[-1][-1]

	def helper(self, sub_a):
		return sum(sub_a) / len(sub_a)

