def count(str):
	le = len(str)
	dc = 26
	max = 0
	if le <= 2:
		return 0
	my_list = frequency(str)
	m = len(my_list)
	if le < dc:
		max = le
	else:
		max = dc
	sm = sys.maxsize - 1
	for i in range(1, max + 1):
		if le % i == 0:
			mov = moves(le, my_list, m, i)
			if mov < sm:
				sm = mov
	return sm

def frequency(str):
	my_list = [0] * 26
	for x in str:
		my_list[ord(x) - 65] += 1
	my_list.sort(reverse=True)
	k = 0
	for x in my_list:
		k += 1
		if x == 0:
			break
	return my_list[:k + 1]

def moves(le, freq, m, n):
	avg = le / n
	mov = 0
	if n == m:
		for x in freq:
			if x <= avg:
				break
			mov += x - avg
	elif n < m:
		for i in range(n):
			mov += abs(freq[i] - avg)
		for i in range(n, m, 1):
			mov += freq[i]
		mov = int(mov)
		mov >>= 1
	else:
		for i in range(len(freq)):
			mov += abs(freq[i] - avg)
		mov += (n - m) * avg
		mov = int(mov)
		mov >>= 1
	return mov
