	states[0][g] = 0
	states[0][0] = 0
	q = deque([(0, g)])

	def process_neib(ineib, gneib):
		if states[ineib][gneib] != WHITE:
			return
		if ineib == m - 1:
			states[ineib][gneib] = states[index][g_left]
		elif gneib == 0:
