class Solution:

	def Factorial(self, n, memory):
		if n <= 1:
			return n
		if memory[n] == -1:
			memory[n] = self.Factorial(n - 1, memory) * n
		return memory[n]

	def Solve(self, n):
		if n <= 2:
			return n
		memory = [-1 for i in range(2 * n + 1)]
		ans = self.Factorial(2 * n, memory) // (self.Factorial(n, memory) * self.Factorial(n + 1, memory)) % mod
		return ans

	def Tab(self, n):
		memory = [0 for i in range(2 * n + 1)]
		(memory[0], memory[1], memory[2]) = (1, 1, 2)
		for i in range(3, 2 * n + 1):
			memory[i] = i * memory[i - 1]
		return memory[2 * n] // (memory[n] * memory[n + 1]) % mod

	def numTrees(self, N):
		return self.Tab(N)

