def remove_zeros(A):
	zeros = 0
	for a in A:
		if a == 0:
			zeros += 1
		else:
			break
	return (zeros, A[zeros:])

def solve(A):
	(zeros, A) = remove_zeros(A)
	while True:
		if A == []:
			return 0
		if len(A) == 1:
			return A[0]
		new_A = [A[i + 1] - A[i] for i in range(len(A) - 1)]
		if zeros > 0:
			new_A = [A[0]] + new_A
			zeros -= 1
		new_A.sort()
		(new_zeros, A) = remove_zeros(new_A)
		zeros += new_zeros
