class Solution:

	def largestSubsquare(self, N, A):
		m = [[[0 for _ in range(N)] for _ in range(N)] for _ in range(2)]
		for i in range(N):
			m[0][i][0] = 1 if A[i][0] == 'X' else 0
			for j in range(1, N):
				if A[i][j] == 'X':
					m[0][i][j] = m[0][i][j - 1] + 1
		for j in range(N):
			m[1][0][j] = 1 if A[0][j] == 'X' else 0
			for i in range(1, N):
				if A[i][j] == 'X':
					m[1][i][j] = m[1][i - 1][j] + 1
		ans = 0
		for i in range(N):
			for j in range(N):
				d = min(m[0][i][j], m[1][i][j])
				while d > 0:
					if m[0][i - d + 1][j] >= d and m[1][i][j - d + 1] >= d:
						ans = max(d, ans)
						break
					d -= 1
		return ans

class Solution:

	def get_hor_mat(self, n, a, hor):
		for i in range(n):
			for j in range(n):
				if i >= 0 and j == 0:
					if a[i][j] == 'X':
						hor[i][j] = 1
					else:
						hor[i][j] = 0
				elif a[i][j] == 'X':
					hor[i][j] = hor[i][j - 1] + 1
				else:
					continue

	def get_ver_mat(self, n, a, ver):
		for i in range(n):
			for j in range(n):
				if i == 0 and j >= 0:
					if a[i][j] == 'X':
						ver[i][j] = 1
				elif a[i][j] == 'X':
					ver[i][j] = ver[i - 1][j] + 1

	def largestSubsquare(self, n, a):
		hor = [[0 for j in range(n)] for i in range(n)]
		ver = [[0 for j in range(n)] for i in range(n)]
		max_square = 0
		self.get_hor_mat(n, a, hor)
		self.get_ver_mat(n, a, ver)
		for i in range(n - 1, -1, -1):
			for j in range(n - 1, -1, -1):
				min_val = min(hor[i][j], ver[i][j])
				while min_val > max_square:
					if ver[i][j - min_val + 1] >= min_val and hor[i - min_val + 1][j] >= min_val:
						max_square = min_val
					min_val -= 1
		return max_square

