class Solution:

	def largestSubsquare(self, N, A):
		B = [[0] * N for i in range(N)]
		for row in range(N):
			for i in reversed(range(N)):
				if A[row][i] == 'X':
					if i == N - 1:
						B[row][i] = 1
					else:
